### C++

```cpp
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int min_k_prefix_length(int n, int k, const string& s) {
    // 记录所有补给点（字符 '1'）的下标
    vector<int> pos;
    for (int i = 0; i < n; i++) {
        if (s[i] == '1') {
            pos.push_back(i);
        }
    }

    int m = (int)pos.size();

    // 补给点总数不足 k 时，无解
    if (m < k) {
        return -1;
    }

    // 构造扩展数组，处理环形赛道
    vector<int> ext(2 * m);
    for (int i = 0; i < m; i++) {
        ext[i] = pos[i];
        ext[i + m] = pos[i] + n;
    }

    int ans = n + 1;

    // 枚举每个补给点作为起点，取连续 k 个补给点的区间长度
    for (int i = 0; i < m; i++) {
        int length = ext[i + k - 1] - ext[i] + 1;
        if (length < ans) {
            ans = length;
        }
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n, k;
        string s;
        cin >> n >> k >> s;

        cout << min_k_prefix_length(n, k, s) << '\n';
    }

    return 0;
}
